>Name + Number printing: <?=money((float)setting('printing_charge','150'))?></div></div><?php endif;?><div class="flex gap-3"><input name="qty" type="number" value="1" min="1" max="20" class="w-20 rounded-xl border-slate-200"><button type="button" onclick="doAdd()" class="shine grad600 text-white flex-1 rounded-xl py-3 font-black">Add to Cart</button><button type="button" onclick="doBuy()" class="bg-slate-950 text-white rounded-xl px-5 font-black">Buy Now</button></div></form><div class="grid grid-cols-3 gap-2 mt-6"><div class="p-3 rounded-2xl border line bg-[var(--surface-2)] text-center text-xs"><b>Cash on Delivery</b><div class="text-slate-400 mt-1">Pay at doorstep</div></div><div class="p-3 rounded-2xl border line bg-[var(--surface-2)] text-center text-xs"><b>7 Day Return</b><div class="text-slate-400 mt-1">Easy returns</div></div><div class="p-3 rounded-2xl border line bg-[var(--surface-2)] text-center text-xs"><b>100% Original</b><div class="text-slate-400 mt-1">Quality checked</div></div></div>
