eview title" class="rounded-xl border-slate-200"></div><textarea required name="review" placeholder="Your review" class="w-full rounded-xl border-slate-200 min-h-24"></textarea><button class="grad600 text-white rounded-xl py-3 px-5 font-black">Submit Review</button></form><?php else:?><div class="mt-4 p-4 rounded-2xl bg-slate-50 text-sm">Login to leave a review.</div><?php endif;?></section></div></div></div><section class="mt-10 max-w-[1480px] mx-auto"><div class="flex items-center justify-between mb-4"><h2 class="text-2xl sm:text-3xl font-black">Related Products</h2><a href="/category/<?=e($p['type'])?>" class="text-sm font-black text-[var(--accent-soft)]">View All →</a></div><div class="grid grid-cols-2 sm:grid-cols-3 gap-3 sm:gap-4"><?php $rel=$pdo->prepare("SELECT p.*,c.name category_name,c.slug category_slug,(SELECT image FROM product_images WHERE product_id=p.id ORDER BY sort_order,id LIMIT 1) AS image FROM products p JOIN categories c ON c.id=p.category_id WHERE p.status=1 AND c.type=? AND p.id<>? ORDER BY p.is_best_seller DESC,p.featured DESC,p.id DESC LIMIT 3");$rel->execute([$p['type'],$p['id']]);$relatedProducts=$rel->fetchAll();foreach($relatedProducts as $rp){$orig=$p;$p=$rp;include __DIR__.'/includes/product_card.php';$p=$orig;} ?></div></section><script>
let selected={size:'M',color:'Black'};document.querySelectorAll('.sizeBtn').forEach(b=>b.onclick=()=>{selected.size=b.dataset.size;document.querySelectorAll('.sizeBtn').forEach(x=>x.classList.remove('bg-slate-950','text-white'));b.classList.add('bg-slate-950','text-white')});document.querySelectorAll('.colorBtn').forEach(b=>b.onclick=()=>{selected.color=b.dataset.color;document.querySelectorAll('.colorBtn').forEach(x=>x.classList.remove('bg-slate-950','text-white'));b.classList.add('bg-slate-950','text-white')});document.querySelector('[data-size="M"]')?.click();document.querySelector('[data-color="Black"]')?.click();
async function doAdd(buy=false){const f=new FormData(document.getElementById('productForm'));let body=Object.fromEntries(f.entries());body.size=selected.size;body.color=selected.color;body.qty=Number(body.qty||1);const res=await fetch('/api/cart.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':<?=json_encode(csrf_token())?>},body:JSON.stringify(body)});const d=await res.json();if(d.ok){if(buy)location.href='/checkout.php';else location.href='/cart.php';}else alert(d.message||'Unable to add to cart');}function doBuy(){doAdd(true)}
document.querySelectorAll('.tabBtn').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.tabBtn').forEach(x=>x.classList.remove('border-blue-600','text-slate-900'));document.querySelectorAll('.tabBtn').forEach(x=>x.classList.add('text-slate-500'));btn.classList.add('border-blue-600','text-slate-900');document.querySelectorAll('[data-panel]').forEach(p=>p.classList.add('hidden'));document.querySelector('[data-panel="'+btn.dataset.tab+'"]').classList.remove('hidden')});
const content=document.getElementById('productContent'), showMore=document.getElementById('showMore');const rawWords=(content.innerText||'').trim().split(/\s+/);if(rawWords.length<=200)showMore.style.display='none';else{const full=content.innerHTML;const tmp=document.createElement('div');tmp.innerHTML=full;let count=0;const walker=document.createTreeWalker(tmp,NodeFilter.SHOW_TEXT);let n;const nodes=[];while(n=walker.nextNode())nodes.push(n);nodes.forEach(t=>{if(count>=200){t.textContent='';return;}const words=t.textContent.trim().split(/\s+/).filter(Boolean);if(count+words.length>200){const keep=words.slice(0,200-count).join(' ');t.textContent=keep+'…';count=200;}else count+=words.length;});content.innerHTML=tmp.innerHTML;let expanded=false;showMore.onclick=()=>{expanded=!expanded;content.innerHTML=expanded?full:tmp.innerHTML;showMore.innerHTML=expanded?'Show less <span class="iconify" data-icon="solar:alt-arrow-up-linear"></span>':'Show more <span class="iconify" data-icon="solar:alt-arrow-down-linear"></span>';}};
</script>

